css:
@keyframes type {
  from {
    width: 0;
  }

  to {
    width: 21ch;
  }
}

@keyframes blink {
  50% {
    border-right-color: transparent;
  }
}

.terminal {
  margin: 24px;
  padding: 20px;
  border-radius: 10px;
  background-color: #18181b;
}

.typed {
  width: 21ch;
  margin: 0;
  overflow: hidden;
  border-right: 2px solid #fb923c;
  color: #fafafa;
  font-family: ui-monospace, Consolas, "Courier New", monospace;
  font-size: 18px;
  white-space: nowrap;
  animation: type 2s steps(21) both, blink 800ms steps(1) infinite;
}

@media (prefers-reduced-motion: reduce) {
  .typed {
    animation: none;
  }
}
